/* Palitra Love: content first, optional story. Navigation and hero share 800px. */
.brand-lockup{display:flex;align-items:center;gap:16px;flex:0 0 auto}
.brand-lockup h1{max-width:none;margin:0;color:var(--muted);font-family:var(--font-heading);font-style:normal;font-weight:400;font-size:14px;line-height:1.25;white-space:nowrap}
/* A media download must never cover the offer with the page loader. */
body[data-page="home"]{padding-bottom:var(--cookie-space,0px)}
body[data-page="home"] #page-loader{display:none!important}
body[data-page="home"] [hidden]{display:none!important}
body[data-page="home"] #zayavka,body[data-page="home"] #hero-content{scroll-margin-top:calc(var(--header-height,0px) + 16px)}
.hero-shell{position:relative;padding:0;background:var(--bg);color:var(--surface);isolation:isolate}
.hero{position:relative;display:flex;align-items:center;width:100%;height:min(56.25vw,calc(100svh - var(--header-height,0px) - var(--cookie-space,0px)));min-height:var(--hero-content-height,420px);padding:0;overflow:clip;background:var(--bg);color:var(--surface);isolation:isolate}
.hero-stage{position:absolute;top:50%;left:50%;height:max(100%,56.25vw);aspect-ratio:16/9;background:var(--bg) url("https://palitra-love-draft-1.synapsebusiness.ru/assets/video/hero-poster.jpg") center/cover no-repeat;transform:translate(-50%,-50%);overflow:hidden}
.hero-stage video{position:absolute;z-index:1;inset:0;display:block;width:100%;height:100%;object-fit:cover}
.hero-main{position:absolute;top:50%;left:3%;transform:translateY(-50%);z-index:4;width:44%;max-width:640px;margin:0;padding:24px;background:var(--video-scrim);border-radius:4px}
#hero-title{margin:0;font-family:var(--font-heading);font-style:normal;font-weight:700;font-size:clamp(26px,2.7vw,46px);line-height:1.12;text-wrap:pretty}
.hero-subtitle{margin:12px 0 0;font-size:17px;line-height:1.4}
.hero-actions{display:grid;gap:8px;max-width:360px;margin-top:18px}
.hero-actions .button{display:flex;align-items:center;justify-content:center;min-height:48px;padding:10px 16px;text-align:center;line-height:1.3}
.hero-actions .hero-telegram{background:var(--paper);color:var(--text)}
.hero-actions .button.outline{border-color:var(--line);color:var(--surface);background:var(--clear)}
.hero-playback{display:flex;align-items:center;flex-wrap:wrap;gap:0 12px;margin-top:8px}
.hero-playback button{min-height:44px;padding:8px 0;background:var(--clear);color:var(--surface);font-family:var(--font-body);font-style:normal;font-weight:400;font-size:14px;line-height:1.3;text-align:left;text-decoration:underline;text-underline-offset:4px}
.hero-video-status{margin:4px 0 0;font-size:14px;line-height:1.3}
.hero-shell :focus-visible,.contact-actions a:focus-visible{outline:3px solid var(--gold);outline-offset:4px}
.hero-overlay{position:absolute;z-index:2;opacity:0;visibility:hidden;pointer-events:none;transition:opacity .3s ease}
.hero-overlay.is-visible{opacity:1;visibility:visible}
/* Story captions stay in the right half, separate from the permanent offer. */
#hero-sms{top:30%;left:60%;width:25%;padding:12px;border-radius:10px;background:var(--surface);color:var(--ink);box-shadow:0 2px 10px var(--shadow);font-size:clamp(12px,1vw,16px);font-weight:700;line-height:1.3}
#hero-offer{top:8%;left:60%;width:36%;padding:16px;border:1px solid var(--gold);border-radius:3px;background:var(--video-scrim);color:var(--surface)}
#hero-offer strong,#hero-offer span{display:block}
#hero-offer strong{font-family:var(--font-heading);font-style:normal;font-weight:700;font-size:clamp(16px,1.8vw,28px);line-height:1.12}
#hero-offer span{margin-top:8px;font-size:clamp(12px,1vw,16px);line-height:1.3}
#hero-brand{top:55%;left:76%;width:24%;transform:translate(-50%,-50%);transition-duration:.6s}
#hero-brand img{display:block;width:100%;height:auto}
#hero-scroll{left:76%;bottom:16px;display:flex;min-height:44px;align-items:center;justify-content:center;gap:8px;padding:8px 14px;border:1px solid var(--gold);border-radius:999px;color:var(--surface);text-decoration:none;background:var(--video-scrim);transform:translateX(-50%);font-size:14px;line-height:1;white-space:nowrap}
#hero-scroll.is-visible{pointer-events:auto}
#hero-scroll span{font-size:22px;line-height:1;animation:hero-scroll-pulse 1.8s ease-in-out infinite}
#hero-scroll small{font:inherit}
@keyframes hero-scroll-pulse{50%{transform:translateY(3px);opacity:.58}}
.our-work{padding-top:40px}
.work-gallery,.video-review-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}
.work-gallery a{display:block;background:var(--surface)}
.work-gallery img{display:block;width:100%;height:auto}
.video-review-grid video{display:block;width:100%;height:auto}
.hero-deadline{padding:12px;border:1px solid var(--olive)}
.contact-actions{display:flex;flex-wrap:wrap;gap:12px 24px;font-weight:700}
/* Reserve the measured banner footprint for the desktop hero. Keep mobile consent compact. */
body[data-page="home"] .cookie{padding:12px 16px;font-size:14px;line-height:1.4}
body[data-page="home"] .cookie p{margin:4px 0 8px}
body[data-page="home"] .cookie .actions{margin:0;gap:8px}
body[data-page="home"] .cookie button{min-height:44px;padding:8px 16px}
@media(max-width:1100px){.brand-lockup h1{display:none}}
@media(min-width:801px) and (max-width:1100px){nav{gap:16px}.navlinks{gap:10px;font-size:14px}}
@media(max-width:800px){
  .hero{display:block;height:auto;min-height:0;aspect-ratio:auto}
  .hero-stage{position:relative;top:auto;left:auto;width:100%;height:auto;aspect-ratio:16/9;transform:none}
  .hero-main{position:relative;top:auto;left:auto;transform:none;width:100%;max-width:none;margin:0;padding:16px;background:var(--bg);border-radius:0}
  #hero-title{font-size:clamp(24px,4.2vw,30px)}
  .hero-subtitle{margin-top:8px;font-size:15px}
  .hero-actions{max-width:none;margin-top:14px}
  .hero-playback{margin-top:4px}
  #hero-sms,#hero-offer{display:none}
  #hero-brand{width:30%;min-width:110px;left:70%;top:48%}
  #hero-scroll{left:50%;bottom:8px}
  .work-gallery,.video-review-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
  body[data-page="home"] .cookie{bottom:8px;left:8px;right:8px;padding:10px 12px}
}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}.hero-overlay{transition:none}#hero-scroll span{animation:none}}

