    .ps{padding:0;scroll-margin-top:100px}.ps+.ps{margin-top:62px}.ps__title{font-size:clamp(27px,3vw,40px)}.price-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}
    .price-card{overflow:hidden;padding:0;background:var(--surface);border:1px solid var(--line)}.price-card__photo{display:block;width:100%;aspect-ratio:4/5;object-fit:cover}.price-card__body{display:flex;flex-direction:column;padding:22px}.price-card h3{margin:0 0 12px}.price-card__description{margin:0 0 14px;color:var(--muted)}.price-card__button{text-align:center}
