/* Warm surfaces and typography. Hero geometry/playback rules above remain intact. */
body{background:var(--bg);color:var(--text);font-family:var(--font-body)}
/* Keep existing sizes/line heights; use upright headings for offers and products. */
h1,h2,h3{font-family:var(--font-heading);font-style:normal;font-weight:500}
/* Italic marks section titles; quiz questions remain upright for quick scanning. */
h2{font-style:italic}
.quiz-panel h2{font-style:normal}
button,.button,input,select,textarea{font-family:var(--font-body);font-style:normal}
p,li,label,input,select,textarea,button,.button,.price,.pc__price{font-style:normal}
.button,button{background:var(--accent);color:var(--text);border-radius:12px}
.button.outline{color:var(--text);border-color:var(--text);background:var(--clear)}
.button:hover,button:hover{box-shadow:0 0 0 2px var(--text)}
:focus-visible{outline:3px solid var(--text);outline-offset:4px}
input,select,textarea{border-radius:10px;color:var(--text);background:var(--surface);border-color:var(--muted)}
input::placeholder,textarea::placeholder{color:var(--muted);opacity:1}
.eyebrow{color:var(--muted);letter-spacing:.1em}
.band,.quiz-section,.feature,.teacher-class-order,.price-hero{background:var(--surface);color:var(--text)}
.feature .note,.price-hero p{color:var(--muted)}
body:not([data-page="home"]) .hero{background:var(--bg);color:var(--text)}
.teacher-button-outline{border-color:var(--text);color:var(--text)}
.teacher-button-light{color:var(--text);background:var(--bg)}
.trust{border:0;background:var(--clear);gap:16px}
.trust span{background:var(--surface);border:1px solid var(--line);border-radius:16px}
.faq details{padding:24px 0}
.faq summary{font-weight:500}
form,.pnav,.price-error{border-radius:16px;background:var(--surface)}
.our-work h2,.home-products h2,.ps__title{max-width:24ch}
.home-products .grid{grid-template-columns:repeat(2,minmax(0,1fr))}
.grid,.home-products .grid,.price-grid,.quiz-results{gap:32px}
.card,.home-products .card,.teacher-products .card,.quiz-product,.price-card{padding:0;overflow:hidden;border:1px solid var(--line);border-radius:20px;background:var(--surface);color:var(--text)}
.card>div:not(.product-purchase),.quiz-product>div,.price-card__body{padding:24px}
