.price,.pc__price,.price-card .pc__price{font-family:var(--font-body);font-size:clamp(28px,2.5vw,34px);font-weight:700;color:var(--price-ink);line-height:1.2}
.product-purchase .price,.price-card .product-purchase .pc__price{margin:0}
.product-purchase .button{min-height:48px;display:inline-flex;align-items:center;justify-content:center;text-align:center;font-size:14px}
.product-purchase+.note{margin:12px 0 0;font-size:13px;line-height:1.5}
.work-gallery{gap:24px}
.work-gallery a{overflow:hidden;border-radius:18px;background:var(--surface)}
.other-occasions{border-radius:16px;background:var(--surface);border-color:var(--gold)}
/* Only the dedicated boy-discharge price section uses blue, replacing gold here. */
.ps#vypiska .price-card{border-top:4px solid var(--blue)}
.ps#vypiska .product-purchase{border-color:var(--blue)}
.ps#vypiska .pc__price{color:var(--text)}
.footer{background:var(--text);color:var(--on-dark)}
