.hero-shell,.hero,.hero-stage{background-color:var(--bg)}
.hero-main,#hero-offer,#hero-scroll{background-color:var(--video-scrim);color:var(--on-dark)}
.hero-actions .hero-telegram{background:var(--accent);color:var(--text)}
.hero-actions .button{border-radius:3px}
.hero-actions .button.outline{color:var(--on-dark);border-color:var(--on-dark)}
