@media(max-width:800px){
  .home-products .grid{grid-template-columns:1fr}
  .grid,.home-products .grid,.price-grid,.quiz-results{gap:24px}
  .card>div:not(.product-purchase),.quiz-product>div,.price-card__body{padding:20px}
  .hero-main{background:var(--bg);color:var(--text)}
  .hero-actions .button.outline{color:var(--text);border-color:var(--text)}
  .hero-playback button{color:var(--text)}
  .hero-main :focus-visible{outline-color:var(--text)}
}

/* ---- Выравнивание 17.09.2026: единая карточка, ступени сетки, шапка/формы/подвал без переполнений.
   Бренд и содержимое не меняются; правила ниже перекрывают более ранние слои. ---- */
/* Карточка: колонка фиксированного порядка. Медиа 4:5 всегда (фото или заглушка), тело растягивается,
   блок «цена + действия» прижат к низу, поэтому карточки одной строки заканчиваются одинаково. */
.card,.price-card,.quiz-product{display:flex;flex-direction:column;min-width:0}
.product-media,.card>div.product-media,.card>.photo,.price-card>.photo{display:block;width:100%;aspect-ratio:4/5;flex:0 0 auto;padding:0;background:var(--bg)}
.product-media img,.product-media .photo{display:block;width:100%;height:100%;aspect-ratio:auto;object-fit:cover;object-position:var(--photo-focus,50% 50%)}
.product-media--empty,.card>div.product-media--empty{display:flex;align-items:center;justify-content:center;border-bottom:1px solid var(--line)}
.product-media--empty img{width:64px;height:64px;object-fit:contain;opacity:.35}
.card>div:not(.product-purchase):not(.product-media),.price-card__body,.quiz-product>div{display:flex;flex:1;flex-direction:column;min-width:0;padding:20px 20px 22px}
.card h3,.price-card h3,.quiz-product h3{margin:0 0 10px;font-size:clamp(20px,1.7vw,26px);line-height:1.22;overflow-wrap:anywhere;hyphens:auto}
.home-products .card h3{margin-bottom:6px}
.product-name{margin:0 0 12px}
.price-card__description,.card>div>p:not(.price):not(.note):not(.product-name){margin:0 0 14px;color:var(--muted);overflow-wrap:anywhere}
.product-footer{margin-top:auto;display:grid;gap:12px}
.product-purchase{margin-top:auto;display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:10px 14px;padding-top:16px;border-top:1px solid var(--gold)}
.product-footer .product-purchase{margin-top:0}
.price,.pc__price,.price-card .pc__price{margin:0;font-family:var(--font-body);font-size:clamp(22px,1.9vw,28px);font-weight:700;line-height:1.2;color:var(--price-ink);overflow-wrap:anywhere}
.price[data-price-known="false"]{font-size:17px;font-weight:500;color:var(--muted)}
.product-purchase .button{margin:0;min-height:48px;display:inline-flex;align-items:center;justify-content:center;text-align:center;font-size:14px;padding:10px 14px;white-space:nowrap}
.product-footer .note,.product-purchase+.note{margin:0;font-size:13px;line-height:1.45;color:var(--muted)}
.product-footer .button,.card>div>.button,.card>div>button{margin:0;min-height:48px;display:inline-flex;align-items:center;justify-content:center;text-align:center}
.quiz-product .quiz-actions{margin-top:12px}
/* Сетки: телефон 1, планшет 2, десктоп 3 (каталог) / 2 (прайс, главная). */
.grid,.price-ladder{grid-template-columns:repeat(3,minmax(0,1fr))}
.price-grid,.home-products .grid{grid-template-columns:repeat(2,minmax(0,1fr))}
.occasion-side-card{grid-template-columns:minmax(0,560px)}
@media(min-width:481px) and (max-width:800px){
  .grid,.home-products .grid,.price-grid,.price-ladder,.quiz-results{grid-template-columns:repeat(2,minmax(0,1fr))}
  .quiz-results{max-width:none}
  .occasion-side-card{grid-template-columns:minmax(0,560px)}
}
@media(max-width:480px){
  .grid,.home-products .grid,.price-grid,.price-ladder,.quiz-results,.occasion-side-card{grid-template-columns:minmax(0,1fr)}
  .product-purchase{grid-template-columns:minmax(0,1fr)}
  .product-purchase .button{width:100%;white-space:normal}
}
/* Шапка: кнопка корзины компактная, ссылки не выдавливают бренд. */
nav{min-width:0}
.navlinks{min-width:0;flex-wrap:wrap;row-gap:4px}
.navlinks a{white-space:nowrap}
.cart-button{flex:0 0 auto;min-height:44px;padding:8px 14px;font-size:14px;font-weight:700;white-space:nowrap;border-radius:12px}
@media(max-width:800px){.navlinks{flex-wrap:nowrap}.navlinks a{white-space:normal}.cart-button{margin-left:0}}
@media(max-width:480px){nav{gap:6px}.menu{padding:8px 10px;font-size:14px}.cart-button{padding:8px 10px;font-size:13px;min-height:40px}}
/* Фильтры и навигация прайса: касание не меньше 44px, без переносов внутри чипа. */
.categories a,.filter{display:inline-flex;align-items:center;min-height:44px;border-radius:12px}
.pnav a{display:inline-block;white-space:nowrap}
.breadcrumbs,.lead,.hero p{overflow-wrap:anywhere}
/* Формы и колонки: содержимое не шире контейнера. */
.two>*,form,.wrap{min-width:0}
input,select,textarea{min-width:0;max-width:100%}
.consent{gap:10px}
.consent input{flex:0 0 auto;width:18px;height:18px}
@media(max-width:480px){form button,form .button{width:100%}.cookie .actions .button,.cookie .actions button{flex:1 1 auto}}
/* Подвал: длинные адреса и ссылки переносятся, а не вылезают. */
.footer .wrap{min-width:0}
.footer p,.footer a{overflow-wrap:anywhere}
.footer p{margin:0 0 12px}

/* ---- Патч 2: одинаковый низ карточек, корзина и заявка, мобильное меню без переполнения. ---- */
/* Примечание владельца — в содержимом; низ карточки у всех одинаков: цена + «Купить». */
.price-card__body .note{margin:0 0 14px}
.product-footer{display:grid;gap:10px}
.product-purchase{grid-template-columns:minmax(0,1fr) auto}
.product-add{min-height:48px;padding:10px 16px;font-size:14px;white-space:nowrap}
.product-add.is-added{background:var(--gold);color:var(--surface)}
.home-products .product-purchase .button{white-space:normal}
@media(max-width:480px){.product-add,.product-purchase .button{width:100%}}
/* Мобильное меню: контейнер — sticky header (во всю ширину), а не nav с vw-расчётом,
   который выходил за экран при полосе прокрутки. */
@media(max-width:800px){
  header nav{position:static}
  .navlinks{left:0;right:0;width:auto}
}
/* Корзина: панель справа поверх страницы, на телефоне во всю ширину. */
.cart{position:fixed;z-index:40;top:0;right:0;bottom:0;width:min(440px,100%);overflow:auto;padding:20px;background:var(--surface);border-left:1px solid var(--line);box-shadow:-12px 0 32px var(--shadow)}
.cart[hidden]{display:none}
.cart h2{margin:8px 0 12px;font-size:26px}
.cart h3{font-size:18px;margin:14px 0 4px}
.cart [data-cart-close]{position:absolute;top:12px;right:12px;min-height:40px;padding:8px 12px;background:var(--clear);color:var(--text);border:1px solid var(--line)}
.cart-line{display:grid;gap:8px;padding:12px 0;border-top:1px solid var(--line)}
.cart-line__info{display:grid;gap:2px;min-width:0;overflow-wrap:anywhere}
.cart-line__info span{font-size:14px;color:var(--muted)}
.cart-line--missing .cart-line__info span{color:var(--text);font-weight:700}
.cart-line__qty{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.cart-line__qty button{min-width:40px;min-height:40px;padding:6px 10px;background:var(--bg);color:var(--text);border:1px solid var(--line)}
.cart-line__qty .cart-line__remove{margin-left:auto;font-size:13px}
.cart-empty,.cart-summary{font-size:14px;color:var(--muted)}
.cart form{padding:16px;margin-top:12px;border-radius:12px}
.cart form button{min-height:48px}
.cart .note{margin:0}
.order-status{margin:0;font-size:14px;line-height:1.45}
.order-status:empty{display:none}
.order-status[data-state="error"]{color:#8a2e2e;font-weight:700}
.order-status[data-state="success"]{color:var(--text);font-weight:700}
.order-trap{position:absolute;left:-10000px;width:1px;height:1px;opacity:0}
body.cart-open{overflow:hidden}
/* Согласие: checkbox отдельно, текст со ссылкой — одним блоком, без второй колонки. */
.consent{display:flex;align-items:flex-start;gap:10px;font-weight:400}
.consent input{flex:0 0 auto;width:18px;height:18px;margin:4px 0 0}
.consent span{flex:1 1 auto;min-width:0;line-height:1.45;overflow-wrap:anywhere}
.consent span a{color:inherit}
.cart-line--pending .cart-line__info span{color:var(--muted)}
.cart-retry{min-height:36px;padding:6px 12px;font-size:14px}
.cart-summary{display:block;margin:8px 0}
@media(max-width:480px){.cart{padding:16px}.cart-line__qty .cart-line__remove{margin-left:0}}

/* ---- Правки по замечаниям Дарьи 20.09.2026 (реализация 24.09): на телефоне прайс и каталог показывают
   два товара в строке (320/360/390/414), карточка компактная — фото 4:5 без обрезки деталей, название,
   цена и одна кнопка «Купить» (добавляет в корзину). Планшет 481–800 уже показывает две колонки выше. ---- */
@media(max-width:480px){
  .price-grid,body[data-page="catalog"] .grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
  .price-grid .price-card,body[data-page="catalog"] .grid .price-card{border-radius:14px}
  .price-grid .price-card__body,body[data-page="catalog"] .grid .price-card__body{padding:10px 10px 12px;gap:0}
  .price-grid .price-card h3,body[data-page="catalog"] .grid .price-card h3{margin:0 0 6px;font-size:15px;line-height:1.25}
  .price-grid .price-card__description,body[data-page="catalog"] .grid .price-card__description{margin:0 0 8px;font-size:12px;line-height:1.4}
  .price-grid .price-card__body .note,body[data-page="catalog"] .grid .price-card__body .note{margin:0 0 8px;font-size:11px;line-height:1.35}
  /* Одна колонка внутри низа карточки (перекрывает более раннее `minmax(0,1fr) auto`): цена своей строкой
     на всю ширину, ниже «Купить» во всю ширину — «10 000 руб.» и «Цена уточняется» не рвутся. */
  .price-grid .product-purchase,body[data-page="catalog"] .grid .product-purchase{grid-template-columns:minmax(0,1fr);gap:6px;padding-top:8px}
  .price-grid .pc__price,body[data-page="catalog"] .grid .pc__price{width:100%;font-size:17px;line-height:1.2;white-space:nowrap;overflow-wrap:normal}
  .price-grid .price[data-price-known="false"],body[data-page="catalog"] .grid .price[data-price-known="false"]{font-size:12px;line-height:1.3;white-space:normal}
  .price-grid .product-add,body[data-page="catalog"] .grid .product-add{width:100%;min-height:40px;padding:8px 10px;font-size:13px;border-radius:10px}
  .price-grid .product-media--empty img,body[data-page="catalog"] .grid .product-media--empty img{width:40px;height:40px}
}

/* Правки 29.09.2026: в полосе доверия три утверждения без неподтверждённых чисел. */
@media(min-width:801px){.trust{grid-template-columns:repeat(3,1fr)}}
@media(min-width:481px) and (max-width:800px){.trust span:last-child:nth-child(odd){grid-column:1/-1}}

/* Несколько фото у товара (29.09.2026): лента с привязкой к кадру внутри того же медиа-блока 4:5.
   Телефон — свайп; компьютер — кнопки и стрелки клавиатуры. Товар с одним фото не меняется. */
.product-gallery{position:relative;overflow:hidden}
.product-gallery__track{display:flex;width:100%;height:100%;overflow-x:auto;overflow-y:hidden;scroll-snap-type:x mandatory;scroll-behavior:smooth;overscroll-behavior-x:contain;scrollbar-width:none;-webkit-overflow-scrolling:touch}
.product-gallery__track::-webkit-scrollbar{display:none}
.product-gallery__track:focus-visible{outline:2px solid var(--olive);outline-offset:-2px}
.product-gallery__track>img{flex:0 0 100%;width:100%;height:100%;scroll-snap-align:start;scroll-snap-stop:always}
.product-gallery>.product-gallery__nav{position:absolute;top:50%;transform:translateY(-50%);width:44px;height:44px;min-height:0;margin:0;padding:0;box-shadow:none;border-radius:50%;border:1px solid var(--line);background:rgba(246,243,238,.88);color:var(--ink);font-size:26px;line-height:1;display:flex;align-items:center;justify-content:center;cursor:pointer}
.product-gallery>.product-gallery__nav--prev{left:8px}
.product-gallery>.product-gallery__nav--next{right:8px}
.product-gallery>.product-gallery__nav:disabled{opacity:0;pointer-events:none}
.product-gallery__count{position:absolute;right:10px;bottom:10px;margin:0;padding:3px 9px;border-radius:999px;background:rgba(43,41,36,.72);color:#fff;font-size:12px;line-height:1.4}
@media(hover:none){.product-gallery>.product-gallery__nav{width:36px;height:36px;font-size:22px;opacity:.9}}
@media(max-width:480px){.product-gallery>.product-gallery__nav{width:32px;height:32px;font-size:20px}.product-gallery>.product-gallery__nav--prev{left:4px}.product-gallery>.product-gallery__nav--next{right:4px}.product-gallery__count{right:6px;bottom:6px;font-size:11px}}
@media(prefers-reduced-motion:reduce){.product-gallery__track{scroll-behavior:auto}}

/* Настоящий логотип PALITRALOVE (PNG клиента, 29.08.2026): горизонтальный тёмный — в шапке, светлый в две строки —
   в подвале и на экране загрузки. Пропорции задаются шириной, высота считается из атрибутов width/height. */
.brand img.brand-logo{width:220px;height:auto;max-width:none}
@media(max-width:800px){.brand img.brand-logo{width:176px}}
@media(max-width:480px){.brand img.brand-logo{width:132px;height:auto}}
.footer-logo{width:auto;height:54px;aspect-ratio:1026/397;margin:0 0 18px}


/* 30.09: настоящие работы на первом экране, история по выбору посетителя. */
.brand-tagline{display:none}
@media(max-width:1350px){.brand-lockup h1{display:none}}
@media(min-width:801px){.navlinks{flex-wrap:nowrap;gap:clamp(9px,1.1vw,16px);font-size:14px}.brand-lockup{gap:0}nav{gap:20px}}
.signature-hero{padding:54px 0 46px;background:var(--bg);color:var(--text)}
.signature-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);align-items:center;gap:52px}
.signature-copy .eyebrow{margin:0 0 22px;font-size:11px;letter-spacing:.16em}
.signature-copy #hero-title{max-width:10ch;margin:0;font-size:clamp(42px,4.5vw,64px);font-weight:400;line-height:1.08;letter-spacing:-.045em;text-wrap:balance}
.signature-copy #hero-title em{font-weight:400;color:#687345}
.signature-lead{max-width:39ch;margin:24px 0 0;font-size:17px;line-height:1.6;color:var(--muted)}
.signature-actions{display:flex;flex-wrap:wrap;gap:12px;margin-top:28px}
.signature-actions .button{display:flex;align-items:center;justify-content:space-between;gap:22px;min-height:52px;padding:14px 20px;border-radius:6px;font-size:14px;background:#687345;color:#fff}
.signature-actions .button.outline{background:transparent;color:var(--text);border:1px solid var(--line)}
.signature-actions .button:hover{box-shadow:none;background:#566137}
.signature-actions .button.outline:hover{background:var(--surface)}
.signature-story-link{display:inline-flex;align-items:center;gap:12px;margin-top:26px;color:var(--text);font-size:14px;text-decoration:none}
.signature-story-link small{display:block;margin-top:2px;color:var(--muted);font-size:11px}
.story-play-icon{flex:none;display:inline-flex;align-items:center;justify-content:center;width:38px;height:38px;border:1px solid var(--line);border-radius:50%;font-size:11px;padding-left:2px}
.signature-story-link:hover .story-play-icon{background:var(--surface);border-color:var(--gold)}
.signature-visual{position:relative;height:540px;min-width:0}
.signature-visual a{position:absolute;display:block;overflow:hidden;text-decoration:none;background:var(--line);border-radius:120px 120px 5px 5px}
.signature-visual img{display:block;width:100%;height:100%;object-fit:cover;transition:transform .6s ease}
.signature-visual a:hover img{transform:scale(1.025)}
.signature-visual a>span{position:absolute;left:12px;right:12px;bottom:12px;display:flex;justify-content:space-between;align-items:center;gap:8px;background:rgba(246,243,238,.94);padding:12px 14px;color:var(--text);font-size:12px;border-radius:3px}
.signature-image-main{inset:0 0 auto auto;width:75%;height:460px}
.signature-image-detail{left:0;bottom:8px;width:43%;height:285px;border:6px solid var(--bg);border-radius:80px 80px 5px 5px!important}
.signature-image-detail img{object-position:52% 50%}
.signature-image-detail>span{left:6px!important;right:6px!important;bottom:6px!important;padding:10px!important;font-size:11px!important}
.signature-caption{position:absolute;right:0;bottom:12px;width:53%;margin:0;font-family:var(--font-heading);font-style:italic;font-size:17px;color:var(--muted);text-align:right}
.brand-story-wrap{padding-bottom:12px}
.brand-story{scroll-margin-top:100px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.brand-story>summary{display:flex;align-items:center;gap:14px;padding:14px 0;cursor:pointer;list-style:none;font-size:14px}
.brand-story>summary::-webkit-details-marker{display:none}
.story-duration{margin-left:auto;color:var(--muted);font-size:12px;white-space:nowrap}
.brand-story .hero{height:auto;min-height:0;aspect-ratio:16/9;width:100%;padding:0;border-radius:6px}
.brand-story .hero-stage{inset:0;transform:none;width:100%;height:100%;aspect-ratio:16/9}
.brand-story #hero-sms{display:block;left:60%;width:29%;font-size:clamp(10px,1.2vw,16px)}
.brand-story #hero-offer{display:block;left:53%;width:43%}
.brand-story #hero-scroll{display:none}
.story-controls{display:flex;align-items:center;flex-wrap:wrap;gap:12px;padding:14px 0}
.story-controls button{background:transparent;color:var(--text);border:1px solid var(--line);font-size:13px;min-height:44px}
body[data-page="home"] .trust{margin-top:24px;gap:0;border-bottom:1px solid var(--line);padding-bottom:24px}
body[data-page="home"] .trust span{padding:0 24px;border:0;border-right:1px solid var(--line);border-radius:0;background:transparent;font-size:13px;color:var(--muted)}
body[data-page="home"] .trust span:first-child{padding-left:0}
body[data-page="home"] .trust span:last-child{border-right:0}
body[data-page="home"] .trust b{color:var(--text);font-size:14px;font-weight:500}
.home-products{padding-top:64px}
.section-intro{max-width:58ch;margin:-8px 0 30px;color:var(--muted);font-size:16px}
.home-products .grid{grid-template-columns:repeat(4,minmax(0,1fr));gap:20px}
.home-products .occasion-card{border:0;border-radius:6px;background:transparent}
.occasion-card-link{display:flex;flex:1;flex-direction:column;text-decoration:none}
.occasion-card .product-media{border-radius:6px;overflow:hidden}
.occasion-card .photo{transition:transform .4s ease}
.occasion-card-link:hover .photo{transform:scale(1.025)}
.occasion-card-copy{display:flex;flex:1;flex-direction:column;padding:18px 0 0}
.home-products .occasion-card h3{font-size:22px;line-height:1.25;margin:0 0 12px}
.occasion-card-copy>span{display:flex;justify-content:space-between;gap:12px;padding-top:10px;margin-top:auto;border-top:1px solid var(--line);font-size:13px;color:var(--muted)}
.other-occasions{border-color:var(--line);border-radius:6px;background:transparent;font-size:14px}
.our-work{padding-top:24px}
.work-gallery{gap:20px}
.work-gallery a{overflow:hidden;border-radius:6px}
.work-gallery img{height:100%;aspect-ratio:4/5;object-fit:cover}
