.home-products .grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.order-step-grid{gap:24px}.order-step-grid h3{font-size:21px}.brand-story{scroll-margin-top:90px}.brand-story #hero-sms{top:28%;padding:8px}.brand-story #hero-offer{padding:10px}.brand-story #hero-offer strong{font-size:clamp(12px,2.1vw,20px)}.brand-story #hero-offer span{font-size:11px}
body[data-page="home"] .trust{grid-template-columns:repeat(3,minmax(0,1fr));gap:0}body[data-page="home"] .trust span{padding:0 16px}body[data-page="home"] .trust span:last-child{grid-column:auto}.home-products{padding-top:44px}
}
