nav{min-height:68px;gap:5px}.brand img.brand-logo{width:140px}.menu{min-width:44px;padding:8px 6px;font-size:12px}.cart-button{padding:8px;font-size:12px;min-height:44px}.brand-lockup{min-width:0}.signature-copy #hero-title{font-size:39px;max-width:12ch;line-height:1.1}.signature-copy .eyebrow{font-size:10px;letter-spacing:.1em}.signature-lead{font-size:15px}.signature-actions{gap:10px}.signature-actions .button{width:100%;justify-content:center;min-height:48px}.signature-visual{height:350px}.signature-image-main{height:290px;width:72%}.signature-image-detail{height:215px;width:46%;bottom:4px;border-width:4px}.signature-visual a>span{font-size:10px;padding:9px;left:8px;right:8px;bottom:8px}.signature-image-detail>span{font-size:10px!important;padding:7px!important}.signature-caption{font-size:12px;bottom:7px;width:49%}.brand-story>summary{font-size:12px;gap:10px}.brand-story>summary>.story-play-icon{width:32px;height:32px}.story-duration{font-size:10px;white-space:normal;max-width:60px;text-align:right}.brand-story #hero-brand{width:28%;left:75%}.brand-story #hero-offer span{display:none}.brand-story #hero-sms{font-size:9px;line-height:1.15;padding:5px;border-radius:5px}
body[data-page="home"] .trust{grid-template-columns:1fr;margin-top:12px;padding-bottom:10px}body[data-page="home"] .trust span{padding:10px 0;border-right:0;border-bottom:1px solid var(--line)}body[data-page="home"] .trust span br{display:none}body[data-page="home"] .trust span b{margin-right:5px}body[data-page="home"] .trust span:last-child{border-bottom:0}
.home-products .grid{gap:22px 12px}.home-products .occasion-card h3{font-size:17px;line-height:1.25}.occasion-card-copy{padding-top:12px}.occasion-card-copy>span{font-size:12px}.section-intro{font-size:14px;margin-top:-10px}.other-occasions{padding:18px}.work-gallery{gap:12px}.order-step-grid{grid-template-columns:1fr;gap:26px;margin-top:28px}.order-step-grid li{display:grid;grid-template-columns:30px 1fr;gap:0 14px}.order-step-grid li>span{padding-top:5px}.order-step-grid h3{margin:0 0 10px;font-size:22px}.order-step-grid p{grid-column:2}.order-steps{padding-top:40px}#zayavka .two{gap:28px}#zayavka form{padding:18px}.request-phone{margin-top:22px}
}
@media(prefers-reduced-motion:reduce){.signature-visual img,.occasion-card .photo{transition:none}.signature-visual a:hover img,.occasion-card-link:hover .photo{transform:none}}

/* Средние экраны: меню раскрывается раньше, чем ссылки начнут теснить логотип и корзину. */
@media(min-width:801px) and (max-width:1000px){
header nav{position:relative}.menu{display:block;margin-left:auto;min-height:44px}.menu-close{display:block;align-self:flex-end;width:44px;height:44px;padding:0;font-size:28px;line-height:1}.navlinks{display:none;position:absolute;top:100%;left:calc(50% - 50vw);right:calc(50% - 50vw);flex-direction:column;flex-wrap:nowrap;gap:0;padding:12px 16px 16px;background:var(--paper);border-bottom:1px solid var(--line);box-shadow:0 12px 20px var(--shadow);z-index:1}.navlinks.is-open{display:flex}.navlinks a{display:flex;align-items:center;min-height:52px;padding:8px 16px;border-bottom:1px solid var(--line);font-size:16px}
}

/* Каталог после встречи 30.09: обратимый показ, компактные карточки и отдельные подробности. */
html[data-flowers="hidden"] [data-flowers],[hidden]{display:none!important}
.product-details{font-size:13px;margin:0 0 10px}.product-details summary{cursor:pointer;color:var(--muted);padding:5px 0;min-height:32px}.product-details summary:focus-visible{outline:2px solid var(--olive);outline-offset:3px}.product-dialog{width:min(900px,calc(100% - 24px));max-height:calc(100dvh - 24px);padding:24px;border:1px solid var(--line);border-radius:20px;background:var(--paper);color:var(--ink);overflow:auto}.product-dialog::backdrop{background:#18261dcc;backdrop-filter:blur(3px)}.product-dialog-open{overflow:hidden}.product-dialog-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:28px}.product-dialog-close{display:block;margin:0 0 12px auto;min-width:44px;min-height:44px;border-radius:50%;font-size:28px;padding:0}.product-dialog-body{min-width:0}.product-dialog h2{font-size:30px;overflow-wrap:anywhere}.product-dialog-body .product-footer{margin-top:24px}.request-context{white-space:pre-line;font-size:13px}.cart form small{font-weight:400;color:var(--muted)}
@media(max-width:800px){.categories{flex-wrap:nowrap;overflow-x:auto;overscroll-behavior-x:contain;padding:4px 0 12px;margin-bottom:16px}.categories>*{flex:0 0 auto;white-space:nowrap}.product-dialog-layout{grid-template-columns:minmax(0,1fr)}.product-dialog{padding:16px}.product-dialog .product-media{max-height:55dvh}.product-dialog h2{font-size:25px}.product-dialog .product-media img{object-fit:contain}.product-details{margin-bottom:6px}}

html:not([data-flowers="hidden"]) [data-no-flowers]{display:none!important}

html[data-flowers="hidden"] .work-gallery{grid-template-columns:repeat(2,minmax(0,1fr))}.catalog-empty{grid-column:1/-1}

/* Обложки из архива имеют разное соотношение сторон. Их собственная высота не должна
   увеличивать медиа 4:5 и весь ряд карточек; геометрию задаёт контейнер, а не картинка. */
.product-card>.product-media,.product-dialog .product-media{position:relative;min-height:0;overflow:hidden}
.product-card>.product-media:not(.product-media--empty)>img,.product-card>.product-media>.product-gallery__track,
.product-dialog .product-media:not(.product-media--empty)>img,.product-dialog .product-media>.product-gallery__track{position:absolute;inset:0;width:100%;height:100%}

/* Каталог начинает показ товаров сразу после заголовка, без высоты видеоблока главной. */
body[data-page="catalog"] .hero{display:block;height:auto;min-height:0;padding:16px 0 12px}
body[data-page="catalog"] .hero h1{font-size:clamp(32px,4vw,48px);margin:0 0 12px}
body[data-page="catalog"] .hero+section{padding-top:20px}
body[data-page="catalog"] .hero .actions:empty{display:none}

/* ---- Витрина по замечаниям Дарьи 05.10.2026 (ориентир — понятный магазин, как posharam.ru).
   Слой только добавляется в конец и перекрывает прежние правила; прежние правила не удалены.
   Шапка: значки меню и корзины с доступными именами; меню — выезжающая панель с 12 категориями.
   Первый экран: фото Дарьи с шарами и текст поверх него. Карточка: фото → название без разрывов слов →
   две округлые кнопки с белым текстом: цена (открывает состав) и значок корзины. ---- */
:root{--shop-btn:#5f6a3a;--shop-btn-hover:#4f5a2e;--shop-cart:#6b5a3e;--shop-cart-hover:#56482f;--shop-radius:999px}
.visually-hidden{position:absolute!important;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);clip-path:inset(50%);white-space:nowrap;border:0}
.icon{display:block;width:24px;height:24px;flex:0 0 auto}

/* Шапка. Без backdrop-filter: фильтр делает шапку контейнером для position:fixed, и панель меню
   обрезалась бы высотой шапки. */
@supports ((backdrop-filter:blur(10px)) or (-webkit-backdrop-filter:blur(10px))){header{-webkit-backdrop-filter:none;backdrop-filter:none;background:var(--bg)}}
header nav{position:relative;gap:12px}
.brand-lockup,header nav>.brand{flex:0 1 auto;min-width:0}
.header-phone{margin-left:auto}
@media(max-width:800px){header nav>.cart-button{margin-left:auto}}
.icon-button,.menu.icon-button,.cart-button.icon-button{position:relative;display:inline-flex;align-items:center;justify-content:center;width:46px;height:46px;min-width:46px;min-height:46px;margin:0;padding:0;border:1px solid var(--line);border-radius:var(--shop-radius);background:var(--surface);color:var(--text);font-size:0;line-height:1}
.icon-button:hover{border-color:var(--gold)}
.icon-button:focus-visible{outline:2px solid var(--shop-btn);outline-offset:2px}
.menu.icon-button{order:-1;margin-right:4px}
.cart-button .cart-count{position:absolute;top:-4px;right:-4px;min-width:20px;height:20px;padding:0 5px;border-radius:var(--shop-radius);background:var(--shop-cart);color:var(--surface);font-size:11px;font-weight:700;line-height:20px;text-align:center}
.header-phone{flex:0 0 auto;font-weight:700;text-decoration:none;white-space:nowrap;color:var(--text)}
@media(max-width:800px){.header-phone{display:none}}
/* Меню — панель с категориями на всех ширинах (как в магазинах-ориентирах). */
.navlinks,header .navlinks{display:none;position:fixed;top:0;bottom:0;left:0;right:auto;z-index:40;width:min(360px,88vw);max-height:none;flex-direction:column;flex-wrap:nowrap;gap:0;margin:0;padding:12px 16px 24px;overflow-y:auto;background:var(--surface);border:0;border-right:1px solid var(--line);box-shadow:0 0 40px var(--shadow);justify-content:flex-start}
.navlinks.is-open{display:flex}
.navlinks .menu-close{display:inline-flex;align-items:center;justify-content:center;align-self:flex-end;width:44px;height:44px;min-height:44px;padding:0;border-radius:var(--shop-radius);background:var(--bg);color:var(--text);font-size:26px;line-height:1}
.navlinks__title{margin:14px 0 4px;font-size:12px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:var(--muted)}
.navlinks a,header .navlinks a{display:flex;align-items:center;min-height:46px;padding:6px 4px;border-bottom:1px solid var(--line);font-size:16px;white-space:normal;text-decoration:none}
.navlinks a:hover{color:var(--shop-btn)}

/* Округлые кнопки */
.button.pill,button.pill,.pill{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:12px 22px;border:0;border-radius:var(--shop-radius);background:var(--shop-btn);color:var(--surface);font-weight:700;text-align:center;text-decoration:none;white-space:normal}
.button.pill:hover,button.pill:hover{background:var(--shop-btn-hover)}
.pill--light,.button.pill.pill--light{background:color-mix(in srgb,var(--text) 45%,transparent);color:var(--surface);border:1.5px solid var(--surface)}
.button.pill.pill--light:hover{background:color-mix(in srgb,var(--text) 65%,transparent)}

/* Первый экран: фото и текст поверх. Дарья 06.10.2026 («Не нравятся шрифты», ориентир — мобильный первый
   экран магазина-ориентира): без засечек — локальный Palitra Golos, лёгкий вес 500, компактные размеры,
   заголовок и подпись по центру с авто-полями в нижней части фото. Фото hero-darya, тексты и две кнопки
   («Выбрать в каталоге», «Подберите за меня набор») не меняются; шрифты форм и каталога не трогаем.
   Каскад: глобальное `#hero-title` (строка видео-истории, специфичность 1,0,0 — Lora 700, clamp 26–46px)
   перебивало прежнее `.shop-hero h1` (0,1,1). Селектор `.shop-hero #hero-title` (1,1,0) ниже в файле
   выигрывает у него и у `.signature-copy #hero-title` только внутри первого экрана; видео-история и
   прежние правила не изменены. */
.shop-hero{position:relative;display:flex;align-items:flex-end;min-height:min(78vh,720px);padding:0;overflow:hidden;background:var(--text);color:var(--surface);isolation:isolate}
.shop-hero__media,.shop-hero__media img{position:absolute;inset:0;width:100%;height:100%}
.shop-hero__media{z-index:-2;display:block}
/* Кадр на широком экране — верх фото: шары, без крупной личной надписи на сфере. */
.shop-hero__photo{object-fit:cover;object-position:50% 18%}
.shop-hero::after{content:"";position:absolute;inset:0;z-index:-1;background:linear-gradient(180deg,transparent 25%,color-mix(in srgb,var(--text) 35%,transparent) 55%,color-mix(in srgb,var(--text) 78%,transparent) 100%)}
.shop-hero__content{position:relative;max-width:720px;margin:0 auto;padding:48px 0 52px;text-align:center}
.shop-hero__eyebrow{margin:0 0 12px;font-size:12px;font-weight:500;letter-spacing:.14em;text-transform:uppercase;color:var(--surface)}
.shop-hero h1,.shop-hero #hero-title{max-width:20ch;margin:0 auto 10px;font-family:var(--font-body);font-style:normal;font-weight:500;font-size:clamp(24px,2.5vw,34px);line-height:1.2;letter-spacing:-.01em;text-align:center;text-wrap:balance;color:var(--surface);text-shadow:0 1px 12px color-mix(in srgb,var(--text) 45%,transparent)}
.shop-hero__lead{max-width:40ch;margin:0 auto 22px;font-size:clamp(14px,1.2vw,16px);font-weight:400;line-height:1.5;text-align:center;color:var(--surface);text-shadow:0 1px 8px color-mix(in srgb,var(--text) 50%,transparent)}
.shop-hero__actions{display:flex;flex-wrap:wrap;justify-content:center;gap:12px}
.shop-hero__actions .pill{min-height:48px;padding:12px 22px;font-size:15px;font-weight:600;line-height:1.3}
/* Кольцо фокуса на тёмном фото — белое (глобальное тёмное `:focus-visible` на фото не видно). */
.shop-hero :focus-visible{outline:3px solid var(--surface);outline-offset:3px}
@media(max-width:720px){
  .shop-hero{min-height:calc(100svh - 68px);max-height:860px}
  .shop-hero__photo{object-position:50% 38%}
  .shop-hero::after{background:linear-gradient(180deg,transparent 32%,color-mix(in srgb,var(--text) 45%,transparent) 58%,color-mix(in srgb,var(--text) 84%,transparent) 100%)}
  .shop-hero__content{padding:32px 0 32px}
  .shop-hero__eyebrow{margin-bottom:10px}
  .shop-hero h1,.shop-hero #hero-title{margin-bottom:8px;font-size:clamp(22px,6.5vw,26px)}
  .shop-hero__lead{margin-bottom:18px;font-size:14px}
  .shop-hero__actions{display:grid;grid-template-columns:1fr;gap:10px;width:100%;max-width:420px;margin:0 auto}
  .shop-hero__actions .pill{width:100%}
}

/* Каталог: категории — ряд округлых кнопок */
.shop{padding:56px 0}
.shop h2{margin-bottom:18px}
.shop-categories{margin:0 0 24px}
.shop-categories__list{display:flex;flex-wrap:wrap;gap:8px;margin:0;padding:0;list-style:none}
.shop-category{display:inline-flex;align-items:center;gap:8px;min-height:42px;padding:8px 16px;border:1px solid var(--line);border-radius:var(--shop-radius);background:var(--surface);color:var(--text);font-size:15px;font-weight:600;text-decoration:none;white-space:nowrap}
.shop-category:hover{border-color:var(--shop-btn)}
.shop-category[aria-current="true"],.shop-category[aria-current="page"]{background:var(--shop-btn);border-color:var(--shop-btn);color:var(--surface)}
.shop-category__count{min-width:22px;padding:0 6px;border-radius:var(--shop-radius);background:var(--bg);color:var(--muted);font-size:12px;line-height:20px;text-align:center}
.shop-category[aria-current="true"] .shop-category__count,.shop-category[aria-current="page"] .shop-category__count{background:color-mix(in srgb,var(--surface) 22%,transparent);color:var(--surface)}
.shop-category--empty{color:var(--muted)}
@media(max-width:720px){
  .shop{padding:40px 0}
  .shop-categories{margin:0 -16px 18px;overflow-x:auto;-webkit-overflow-scrolling:touch;scrollbar-width:none}
  .shop-categories::-webkit-scrollbar{display:none}
  .shop-categories__list{flex-wrap:nowrap;padding:2px 16px 6px;width:max-content}
  .shop-category{min-height:40px;padding:8px 14px;font-size:14px}
}
.shop-more{margin:28px 0 0;text-align:center}
.catalog-empty{grid-column:1/-1;margin:0;padding:22px;border:1px dashed var(--line);border-radius:16px;background:var(--surface);color:var(--muted)}

/* Карточки: одна структура для главной, каталога и прайса */
body .grid[data-products],body .price-grid{grid-template-columns:repeat(4,minmax(0,1fr));gap:20px}
@media(max-width:1100px){body .grid[data-products],body .price-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:800px){body .grid[data-products],body .price-grid,body[data-page="catalog"] .grid[data-products]{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}}
body .product-card{border-radius:18px}
body .product-card .price-card__body{display:flex;flex:1 1 auto;flex-direction:column;gap:0;padding:12px 12px 14px;container-type:inline-size}
body .product-card h3.pc__title{margin:0 0 12px;font-family:var(--font-body);font-size:16px;font-weight:600;line-height:1.3;color:var(--text);overflow-wrap:normal;word-break:normal;hyphens:manual;-webkit-hyphens:manual}
body .product-card .product-footer{margin-top:auto;display:block}
body .product-card .product-purchase{display:flex;flex-wrap:nowrap;align-items:center;gap:8px;margin:0;padding:0;border:0}
body .product-card .product-purchase .product-price{flex:1 1 auto;min-width:0;width:auto;min-height:44px;margin:0;padding:8px 14px;border:0;border-radius:var(--shop-radius);background:var(--shop-btn);color:var(--surface);font-family:var(--font-body);font-size:16px;font-weight:700;line-height:1.2;text-align:center;white-space:nowrap;overflow-wrap:normal;cursor:pointer}
body .product-card .product-purchase .product-price:hover{background:var(--shop-btn-hover)}
body .product-card .product-purchase .product-price[data-price-known="false"]{font-size:13px;font-weight:600;white-space:normal}
body .product-card .product-purchase .product-add{flex:0 0 44px;width:44px;height:44px;min-width:44px;min-height:44px;margin:0;padding:0;border:0;border-radius:var(--shop-radius);background:var(--shop-cart);color:var(--surface);font-size:0;display:inline-flex;align-items:center;justify-content:center}
body .product-card .product-purchase .product-add:hover{background:var(--shop-cart-hover)}
body .product-card .product-purchase .product-add.is-added{background:var(--shop-btn)}
body .product-card .product-purchase :is(.product-price,.product-add):focus-visible{outline:2px solid var(--text);outline-offset:2px}
/* Белый текст на кнопках и там, где прежние правила разделов задают цвет цены через id (`.ps#vypiska .pc__price`). */
body .product-card .product-purchase :is(.product-price,.product-add){color:var(--surface)!important}
@container (max-width:160px){
  body .product-card .product-purchase{gap:6px}
  body .product-card .product-purchase .product-price{padding:8px 8px;font-size:14px;letter-spacing:-.01em}
  body .product-card .product-purchase .product-price[data-price-known="false"]{font-size:11px}
  body .product-card .product-purchase .product-add{flex-basis:40px;width:40px;height:40px;min-width:40px;min-height:40px}
}
/* Самые узкие карточки (телефон 320 px): две те же округлые кнопки одна под другой во всю ширину —
   одинаково во всех карточках ряда, цена не обрезается и не переносится посреди числа. */
@container (max-width:132px){
  body .product-card .product-purchase{flex-direction:column;align-items:stretch}
  body .product-card .product-purchase .product-price{flex:0 0 auto;width:100%}
