 .sf-header .sf-actions .sf-icon{width:26px;height:26px}
}


/* Match the product category labels without changing the main navigation. */
.sf-header .sf-mega a{font-family:var(--font-body);font-size:15px;font-weight:600;font-style:normal;line-height:1.55;letter-spacing:normal;text-transform:none}
@media(max-width:720px){.sf-header .sf-mega a{font-size:14px}}


/* Hide these two navigation items throughout the draft. */
.sf-header .sf-links>a[href="/blog"],.sf-header .sf-links>a[href="/important"]{display:none!important}


/* 10.10.2026: способ и время получения в корзине. Скругление и шрифт полей не меняются. */
.order-fulfillment{min-width:0;margin:0;padding:0;border:0}
.order-fulfillment legend{padding:0;margin:0 0 8px;font-weight:700}
.order-fulfillment__choices{display:flex;flex-wrap:wrap;gap:8px}
.order-fulfillment__choices label{display:inline-flex;align-items:center;gap:8px;min-height:44px;padding:8px 14px;border:1px solid var(--line,#ddd);border-radius:999px;background:var(--surface,#fff);font-weight:600;cursor:pointer}
.order-fulfillment__choices label:has(input:checked){border-color:var(--green,#173c2b);box-shadow:inset 0 0 0 1px var(--green,#173c2b)}
.order-fulfillment__choices input[type=radio]{flex:none;width:18px!important;height:18px!important;min-height:0!important;margin:0!important;padding:0!important;accent-color:var(--green,#173c2b)}
.order-hint{display:block;margin:8px 0 0;font-size:13px;font-weight:400;line-height:1.45;color:var(--muted,#6b6b6b)}
[data-delivery-address-field][hidden]{display:none!important}
@media(max-width:380px){.order-fulfillment__choices label{padding:8px 11px;font-size:14px}}


