.palitra-stories__open:focus-visible{outline:3px solid var(--olive,#69723e);outline-offset:4px}
.palitra-stories__toggle{display:flex;justify-content:center;margin-top:24px}
.palitra-stories__more{display:inline-flex;align-items:center;justify-content:center;gap:10px;box-sizing:border-box;min-width:44px;min-height:44px;max-width:100%;margin:0;padding:10px 18px;border:0;border-radius:28px;background:transparent;box-shadow:none;color:#302f2a;font-family:'Nunito Sans',Arial,sans-serif;font-size:16px;font-weight:600;line-height:1.2;letter-spacing:.08em;text-transform:uppercase;white-space:nowrap;cursor:pointer}
.palitra-stories__more:hover{background:transparent;color:#302f2a;text-decoration:underline;text-underline-offset:5px}
.palitra-stories__more:focus-visible{outline:3px solid var(--olive,#69723e);outline-offset:3px}
.palitra-stories__more[hidden]{display:none!important}
.palitra-stories__dialog{box-sizing:border-box;width:min(920px,calc(100% - 24px));max-width:none;max-height:calc(100dvh - 24px);margin:auto;padding:16px;border:0;border-radius:28px;background:#fff;overflow:auto}
